// ── 1. Inputs ───────────────────────────────────────────────────────────────────
const feedsSince = $('Config').first().json.feedsSince;
const feedsSinceDate = new Date(feedsSince);

// Channels - Aggregate output: { data: [ { channel_id, messages: [...] }, ... ] }
let channelGroups = [];
try {
  channelGroups = $('Channels - Aggregate').first().json.data || [];
} catch (e) { channelGroups = []; }

// PDA Config: { data: "```json\n{ clickup_users: {...} }\n```" }
let clickupUsers = {};
try {
  const raw = $('Fetch PDA Config').first().json.data || '';
  const fenceMatch = raw.match(/```json\s*([\s\S]*?)\s*```/);
  const jsonText = fenceMatch ? fenceMatch[1] : raw;
  const parsed = JSON.parse(jsonText);
  clickupUsers = parsed.clickup_users || {};
} catch (e) { clickupUsers = {}; }

// ── 2. Helpers ─────────────────────────────────────────────────────────────────
function toUTCISO(ts) {
  if (!ts) return null;
  if (typeof ts === 'string' && /^\d+$/.test(ts)) {
    return new Date(parseInt(ts, 10)).toISOString();
  }
  if (typeof ts === 'number') {
    return new Date(ts).toISOString();
  }
  const d = new Date(ts);
  return isNaN(d.getTime()) ? null : d.toISOString();
}

function resolveAuthor(msg) {
  // Nested user/author object (legacy shape)
  const userObj = msg.user || msg.author;
  if (userObj) {
    return userObj.username || userObj.name || userObj.email || 'unknown';
  }
  // ClickUp v3 chat messages: user_id only
  if (msg.user_id) {
    return clickupUsers[String(msg.user_id)] || `user_${msg.user_id}`;
  }
  return 'unknown';
}

function cleanMentions(text) {
  // Replace [@Name](#user_mention#id) with plain @Name
  return text.replace(/\[@([^\]]+)\]\(#user_mention#\d+\)/g, '@$1');
}

function truncate(text, max) {
  if (!text) return '';
  return text.substring(0, max);
}

// ── 3. Build message objects from Channel messages ──────────────────────────────
const messages = [];

for (const group of channelGroups) {
  const channelId = group.channel_id;
  const msgs = group.messages || [];

  for (const msg of msgs) {
    const rawTs = msg.date || msg.created_at || msg.date_created || msg.timestamp;
    const timestamp = toUTCISO(rawTs);
    if (!timestamp) continue;
    if (new Date(timestamp) < feedsSinceDate) continue;

    let text = truncate(msg.text || msg.content || '', 1500);
    if (!text) continue;
    text = cleanMentions(text);

    messages.push({
      source_type: 'clickup_chat',
      comment_id: msg.id || null,
      channel_id: channelId,
      author: resolveAuthor(msg),
      text: text,
      timestamp: timestamp
    });
  }
}

// ── 4. Sort ascending by timestamp (oldest first) ────────────────────────────────
messages.sort((a, b) => {
  if (!a.timestamp) return 1;
  if (!b.timestamp) return -1;
  return a.timestamp.localeCompare(b.timestamp);
});

// ── 5. Wrap in fenced JSON block for Obsidian ─────────────────────────────────────
const fence = '```';
const content = `${fence}json\n${JSON.stringify(messages, null, 2)}\n${fence}`;

return [{ json: { content } }];

// Parse the projects index JSON (fenced code block) and flatten/dedupe
// clickup_channel_ids across all active projects into one item per channel.

const raw = $('Fetch Projects Index').first().json.data;
let content = typeof raw === 'string' ? raw : JSON.stringify(raw);

// Strip markdown fence if present
const fenceMatch = content.match(/```json\s*([\s\S]*?)\s*```/);
const jsonText = fenceMatch ? fenceMatch[1] : content;

const projects = JSON.parse(jsonText);

const channelIds = new Set();
for (const project of projects) {
  const ids = project.clickup_channel_ids || [];
  for (const id of ids) {
    if (id) channelIds.add(id);
  }
}

if (channelIds.size === 0) {
  throw new Error('No clickup_channel_ids found across any project in projects index — refusing to proceed with an empty channel set.');
}

return Array.from(channelIds).map(channel_id => ({ json: { channel_id } }));
